# Model-based reflex vacuum agent: remembers what it has seen, stops when all is clean.
class ModelBasedVacuum:
    def __init__(self):
        self.model = {"A": None, "B": None}    # internal state: unknown at start

    def act(self, percept):
        location, status = percept
        self.model[location] = status          # update the model from the percept
        if status == "Dirty":
            self.model[location] = "Clean"     # predicted effect of Suck
            return "Suck"
        if all(s == "Clean" for s in self.model.values()):
            return "NoOp"                      # simple reflex would keep moving
        return "Right" if location == "A" else "Left"

world = {"A": "Clean", "B": "Dirty"}
agent, location, moves = ModelBasedVacuum(), "A", 0
while True:
    action = agent.act((location, world[location]))
    print(f"at {location} ({world[location]}) -> {action}")
    if action == "NoOp":
        break
    if action == "Suck":
        world[location] = "Clean"
    else:
        location = "B" if action == "Right" else "A"
        moves += 1
print("Moves:", moves, "| World:", world)

# Output:
# at A (Clean) -> Right
# at B (Dirty) -> Suck
# at B (Clean) -> NoOp
# Moves: 1 | World: {'A': 'Clean', 'B': 'Clean'}

