# Umbrella HMM: hidden Rain (R) / NoRain (N); observation U (umbrella) or X (no umbrella).
states = ["R", "N"]
start = {"R": 0.5, "N": 0.5}
trans = {"R": {"R": 0.7, "N": 0.3}, "N": {"R": 0.3, "N": 0.7}}
emit = {"R": {"U": 0.9, "X": 0.1}, "N": {"U": 0.2, "X": 0.8}}

def viterbi(obs):
    V = [{s: start[s] * emit[s][obs[0]] for s in states}]
    back = [{}]
    for t in range(1, len(obs)):
        V.append({})
        back.append({})
        for s in states:
            prev, p = max(((r, V[t - 1][r] * trans[r][s]) for r in states), key=lambda x: x[1])
            V[t][s] = p * emit[s][obs[t]]
            back[t][s] = prev
    last = max(V[-1], key=V[-1].get)
    path = [last]
    for t in range(len(obs) - 1, 0, -1):
        path.insert(0, back[t][path[0]])
    return path, V[-1][last]

def forward(obs):
    alpha = {s: start[s] * emit[s][obs[0]] for s in states}
    for o in obs[1:]:
        alpha = {s: sum(alpha[r] * trans[r][s] for r in states) * emit[s][o] for s in states}
    return sum(alpha.values())

obs = ["U", "U", "X", "U", "U"]
path, p = viterbi(obs)
print("Observations:", " ".join(obs))
print("Most likely weather:", " ".join(path), f"(path probability {p:.6f})")
print(f"P(observations) by forward algorithm = {forward(obs):.6f}")

# Output:
# Observations: U U X U U
# Most likely weather: R R N R R (path probability 0.011574)
# P(observations) by forward algorithm = 0.034304

